20	
21	/**
22	 * What an issue's parentage turned out to be.
23	 *
24	 * Three answers, not two. `known: true, parent: 0` is a root issue; `known:
25	 * false` is a read that failed, and the two are not interchangeable -- one
26	 * caller can treat an unknown parent as absent and another cannot. See
27	 * `stackedPrBase` in `branch-placement.ts` for the case that cannot: it decides
28	 * where a pull request merges to, and guessing lands one child's half of a
29	 * feature on the release branch.
30	 */
31	export type ParentIssue = { known: true; parent: number } | { known: false; why: string };
