36	
37	/** GitHub's native sub-issue parent, or undefined when there is none or it could not be asked. */
38	function nativeParent(repo: string, issue: number): number | undefined {
39	  const [owner, name] = repo.split("/", 2);
40	  if (!owner || !name) return undefined;
41	  try {
42	    const data = ghGraphql<{ repository: { issue: { parent: { number: number } | null } } }>(
43	      "query($owner:String!,$repo:String!,$num:Int!){repository(owner:$owner,name:$repo){issue(number:$num){parent{number}}}}",
44	      { owner, repo: name, num: issue },
45	    );
46	    return data.repository.issue.parent?.number;
47	  } catch {
48	    // Not an answer either way: the field is unavailable on some plans and the
49	    // query fails on a transient error. The tag below is the fallback, and it is
50	    // the one Atomaton writes for itself.
51	    return undefined;
52	  }
53	}
54	
55	/**
56	 * The parent issue this one was split out of.
57	 *
58	 * GitHub's native link first, then the `atomaton:parent` tag `create_issue` writes.
59	 * A failure to read the body is `known: false`; a body with no tag and no native
60	 * parent is a root issue.
61	 */
62	export function parentIssueOf(repo: string, issue: number): ParentIssue {
63	  const native = nativeParent(repo, issue);
64	  if (native) return { known: true, parent: native };
65	
66	  const { code, stderr, stdout } = gh("issue", "view", String(issue), "--repo", repo, "--json", "body", "--jq", ".body");
67	  if (code) {
68	    const why = `could not read issue #${issue}: ${stderr.trim() || `gh exited ${code}`}`;
69	    log(`WARN ${why}`);
70	    return { known: false, why };
71	  }
72	  return { known: true, parent: PARENT_TAG.read(stdout) ?? 0 };
73	}

