+  const runtimeTools = `${root}/${TOOLS_DIR}`;
+  const wrote = Bun.spawnSync([
+    "bun",
+    "run",
+    writer,
+    "--config",
+    `${root}/${CONFIG_FILE}`,
+    "--defaults",
+    `${root}/${TOOL_DEFAULTS_FILE}`,
+    "--out",
+    toolsFile,
+    "--hook-base",
+    runtimeTools
